<script setup lang="ts">
import { ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ApiError, post, session, type CurrentUser } from '../api'
const router = useRouter(), route = useRoute(), username = ref(''), password = ref(''), error = ref(''), loading = ref(false)
async function login() { error.value = ''; loading.value = true; try { const result = await post<{ user: CurrentUser }>('/auth/login', { username: username.value, password: password.value }); session.user.value = result.user; session.restored = true; router.replace(typeof route.query.redirect === 'string' ? route.query.redirect : '/') } catch (e) { error.value = e instanceof ApiError ? e.message : '登录失败，请稍后重试' } finally { loading.value = false } }
</script>
<template><div class="login"><section class="login-hero"><div class="login-brand">PM.</div><div class="login-copy"><h1>公司项目<br>一眼看清。</h1><div class="login-accent"/><div class="login-facts"><span>项目</span><span>风险</span><span>经营</span></div></div></section><section class="login-form-area"><form class="login-form" @submit.prevent="login"><h1>欢迎回来</h1><p class="subtitle">登录项目经营系统</p><div class="login-accent"/><div class="field-group"><label>用户名</label><input v-model.trim="username" class="input" autocomplete="username" required/></div><div class="field-group"><label>密码</label><input v-model="password" type="password" class="input" autocomplete="current-password" required/></div><p v-if="error" class="error" role="alert">{{ error }}</p><button class="button primary" :disabled="loading">{{ loading?'登录中…':'登录 →' }}</button><p class="subtitle" style="font-size:12px;margin-top:20px">演示账户：admin / admin（仅可浏览独立演示数据）</p><RouterLink to="/register" class="login-link">没有账户？创建正式账户</RouterLink></form></section></div></template>
